mapper.sql:
a.`del_flag` = 0

    AND a.`archive_no` LIKE CONCAT('%', #{q.archiveNo}, '%')


    AND a.`archive_name` LIKE CONCAT('%', #{q.archiveName}, '%')


    AND a.`ptxmmc` LIKE CONCAT('%', #{q.ptxmmc}, '%')


    AND a.`crzdbh` LIKE CONCAT('%', #{q.crzdbh}, '%')


    AND a.`dkmc` LIKE CONCAT('%', #{q.dkmc}, '%')


    AND a.`xzqh` = #{q.xzqh}


    AND a.`ptsslb` = #{q.ptsslb}


    AND a.`facility_id` = #{q.facilityId}


    AND a.`land_id` = #{q.landId}


    AND a.`archive_year` = #{q.archiveYear}


    AND a.`responsible_dept` = #{q.responsibleDept}


    AND a.`responsible_user` LIKE CONCAT('%', #{q.responsibleUser}, '%')


    AND a.`status` = #{q.status}


    AND a.`secret_level` = #{q.secretLevel}


    AND a.`archive_type` = #{q.archiveType}


    AND a.`source_type` = #{q.sourceType}


    AND a.`archive_date` >= #{q.beginDate}


    AND a.`archive_date` <= #{q.endDate}


    AND a.`create_time` >= CONCAT(#{q.beginCreateTime}, ' 00:00:00')


    AND a.`create_time` <= CONCAT(#{q.endCreateTime}, ' 23:59:59')



    AND EXISTS (
        SELECT 1 FROM `t_archive_file` cf
        WHERE cf.`archive_id` = a.`id` AND cf.`del_flag` = 0

            AND (cf.`category_path` = #{q.categoryPath}
                 OR cf.`category_path` LIKE CONCAT(#{q.categoryPath}, '/%'))


            AND cf.`category_id` = #{q.categoryId}

    )



    AND EXISTS (
        SELECT 1 FROM `t_archive_file` ff
        WHERE ff.`archive_id` = a.`id` AND ff.`del_flag` = 0
          AND ff.`file_name` LIKE CONCAT('%', #{q.fileName}, '%')
    )

mapper.select:
SELECT COUNT(1)
FROM `t_archive` a
WHERE a.`del_flag` = 0
  AND a.`archive_no` = #{archiveNo}

    AND a.`id` <> #{excludeId}
